import fs from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';
const directory='public/processing-runtime';
await fs.mkdir(directory,{recursive:true});
// Remove only assets generated by the earlier P1 probe, never arbitrary files.
for(const file of ['ort.webgpu.min.mjs','ort-wasm-simd-threaded.asyncify.mjs','ort-wasm-simd-threaded.asyncify.wasm'])await fs.rm(path.join(directory,file),{force:true});
const names=['ort.all.min.mjs','ort.wasm.min.mjs','ort-wasm-simd-threaded.jsep.mjs','ort-wasm-simd-threaded.jsep.wasm','ort-wasm-simd-threaded.mjs','ort-wasm-simd-threaded.wasm'];
const assets=[];
for(const file of names){const data=await fs.readFile(`node_modules/onnxruntime-web/dist/${file}`);await fs.writeFile(path.join(directory,file),data);assets.push({file,bytes:data.length,sha256:createHash('sha256').update(data).digest('hex')});}
const lock=JSON.parse(await fs.readFile('package-lock.json','utf8'));
const manifest={version:'1.30.0',integrity:lock.packages['node_modules/onnxruntime-web'].integrity,license:'MIT',assets};
const pinned=JSON.parse(await fs.readFile('src/processing/runtime-manifest.json','utf8'));
if(JSON.stringify(manifest)!==JSON.stringify(pinned))throw Error('Installed runtime assets differ from pinned manifest.');
await fs.writeFile(path.join(directory,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
await fs.copyFile('src/processing/THIRD_PARTY_NOTICES.md',path.join(directory,'THIRD_PARTY_NOTICES.md'));
const transcriptionDirectory=path.join(directory,'transcription');
await fs.mkdir(path.join(transcriptionDirectory,'licenses'),{recursive:true});
await fs.copyFile('src/transcription/THIRD_PARTY_NOTICES.md',path.join(transcriptionDirectory,'THIRD_PARTY_NOTICES.md'));
await fs.copyFile('src/transcription/model-artifacts.json',path.join(transcriptionDirectory,'model-artifacts.json'));
await fs.copyFile('src/transcription/licenses/BasicPitch-LICENSE.txt',path.join(transcriptionDirectory,'licenses','BasicPitch-LICENSE.txt'));
console.log(JSON.stringify(manifest));
